CREATE OR REPLACE FUNCTION private.fin_operation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE ts timestamptz; BEGIN PERFORM pg_advisory_xact_lock(741928301); SELECT started_at INTO ts FROM public.fin_operation_start WHERE id=true; IF TG_OP='UPDATE' AND OLD.operation_test THEN NEW.operation_test:=true; IF (NEW.status,NEW.claimed_by,NEW.reconciled_by,NEW.customer,NEW.money_type,NEW.ref_code,NEW.note,NEW.info_reason,NEW.cancelled_at,NEW.amount,NEW.received_date,NEW.description) IS DISTINCT FROM (OLD.status,OLD.claimed_by,OLD.reconciled_by,OLD.customer,OLD.money_type,OLD.ref_code,OLD.note,OLD.info_reason,OLD.cancelled_at,OLD.amount,OLD.received_date,OLD.description) THEN RAISE EXCEPTION 'Giao dịch thuộc lịch sử kiểm thử chỉ được xem, không xử lý'; END IF; END IF; IF ts IS NOT NULL AND (NEW.transaction_at IS NULL OR NEW.transaction_at<ts) THEN NEW.operation_test:=true; END IF; IF NEW.operation_test AND NEW.gmf_status IN('pending','sending') THEN IF TG_OP='INSERT' THEN RETURN NULL; ELSIF NEW.gmf_status IS DISTINCT FROM OLD.gmf_status THEN RETURN NULL; END IF; END IF; RETURN NEW; END; $$;